local HTML_DQ = string.char(34)

-- توجه (کشف حین تست v01): سرور Teamyar موقع ذخیرهٔ command، رشته‌های HTML Entity کامل (امپرسند+نام+سمی‌کالن،
-- پشت‌سرهم و بدون شکست، مثلاً معادل نوشتاری amp/lt/gt) را که در سورس Lua به یک‌جا نوشته شوند، بی‌صدا
-- Decode می‌کرد و خودِ escape_html را از کار می‌انداخت (امپرسند جای «امپرسند-entity» می‌نشست، و مشابه برای < >).
-- با ساختن این رشته‌ها از طریق Concatenation (نه یک Literal پیوسته)، در متن آپلودشده دیگر آن الگوی
-- پیوسته وجود ندارد و این مشکل دور زده می‌شود.
local AMP_ENTITY = "&" .. "amp;"
local LT_ENTITY = "&" .. "lt;"
local GT_ENTITY = "&" .. "gt;"
local QUOT_ENTITY = "&" .. "quot;"

local function escape_html(value)
    if value == nil then return "" end
    return tostring(value)
        :gsub("&", AMP_ENTITY)
        :gsub("<", LT_ENTITY)
        :gsub(">", GT_ENTITY)
        :gsub(HTML_DQ, QUOT_ENTITY)
end

local function fmt_num(value)
    local n = tonumber(value)
    if n == nil then return "0" end
    local s = tostring(math.floor(n + 0.5))
    local sign = ""
    if s:sub(1, 1) == "-" then
        sign = "-"
        s = s:sub(2)
    end
    return sign .. s:reverse():gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", "")
end

local function fmt_dec1(value)
    local n = tonumber(value)
    if n == nil then return "0.0" end
    return string.format("%.1f", n)
end

local function fmt_pct(part, total)
    local t = tonumber(total) or 0
    if t <= 0 then return 0.0 end
    return (tonumber(part) or 0) / t * 100.0
end

local function safe_str(v, default_v)
    if v == nil or v == "" then return default_v or "—" end
    return tostring(v)
end

