-- توجه (کشف در حین تست v01): تابع REPORT_FN_JDATE که در سایر بات‌های این پروژه دیده می‌شود
-- (fmt_jalali_datetime/fmt_jalali_date قبلی) زیر این نشست/حساب SQL خطای عمومی "sql error" می‌دهد —
-- نه در INFORMATION_SCHEMA.ROUTINES ثبت است و نه در SHOW FUNCTION STATUS دیده می‌شود، برخلاف
-- DATE_FORMAT/FROM_UNIXTIME/NOW که همگی سالم کار می‌کنند. تا شناسایی علت (احتمالاً UDF سمت سرور که
-- روی این Connection/Node لود نشده)، این بات تقویم شمسی را کاملاً سمت Lua (بدون وابستگی به SQL) محاسبه می‌کند.

local function format_duration_days(days)
    if days == nil then return "—" end
    return fmt_dec1(days) .. " روز"
end

-- الگوریتم استاندارد Howard Hinnant (proleptic Gregorian) — روزهای سپری‌شده از epoch 1970-01-01
local function days_from_civil(y, m, d)
    if m <= 2 then y = y - 1 end
    local era
    if y >= 0 then era = math.floor(y / 400) else era = math.floor((y - 399) / 400) end
    local yoe = y - era * 400
    local mm = m + (m > 2 and -3 or 9)
    local doy = math.floor((153 * mm + 2) / 5) + d - 1
    local doe = yoe * 365 + math.floor(yoe / 4) - math.floor(yoe / 100) + doy
    return era * 146097 + doe - 719468
end

-- معکوس days_from_civil (همان الگوریتم Howard Hinnant) — روز از epoch 1970-01-01 -> سال/ماه/روز میلادی
local function civil_from_civil_days(z)
    z = z + 719468
    local era
    if z >= 0 then era = math.floor(z / 146097) else era = math.floor((z - 146096) / 146097) end
    local doe = z - era * 146097
    local yoe = math.floor((doe - math.floor(doe / 1460) + math.floor(doe / 36524) - math.floor(doe / 146096)) / 365)
    local y = yoe + era * 400
    local doy = doe - (365 * yoe + math.floor(yoe / 4) - math.floor(yoe / 100))
    local mp = math.floor((5 * doy + 2) / 153)
    local d = doy - math.floor((153 * mp + 2) / 5) + 1
    local m = mp + ((mp < 10) and 3 or (-9))
    y = y + ((m <= 2) and 1 or 0)
    return y, m, d
end

-- تبدیل میلادی -> شمسی (الگوریتم استاندارد ۳۳ساله؛ صحت‌سنجی‌شده روی چند تاریخ مرجع)
local function gregorian_to_jalali(gy, gm, gd)
    local g_days_in_month = { 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 }
    local gy2 = (gm > 2) and (gy + 1) or gy
    local days = 355666 + (365 * gy) + math.floor((gy2 + 3) / 4) - math.floor((gy2 + 99) / 100) +
        math.floor((gy2 + 399) / 400) + gd
    for i = 1, gm - 1 do
        days = days + g_days_in_month[i]
    end

    local jy = -1595 + (33 * math.floor(days / 12053))
    days = days % 12053
    jy = jy + 4 * math.floor(days / 1461)
    days = days % 1461
    if days > 365 then
        jy = jy + math.floor((days - 1) / 365)
        days = (days - 1) % 365
    end

    local jm, jd
    if days < 186 then
        jm = 1 + math.floor(days / 31)
        jd = 1 + (days % 31)
    else
        jm = 7 + math.floor((days - 186) / 30)
        jd = 1 + ((days - 186) % 30)
    end
    return jy, jm, jd
end

-- FILETIME (تیک) -> {y,m,d,hh,mm,ss} شمسی، کاملاً سمت Lua
local function filetime_to_jalali(raw)
    raw = tonumber(raw)
    if raw == nil or raw <= 0 then return nil end
    local unix_seconds = raw / 10000000 - 11644473600
    local days = math.floor(unix_seconds / 86400)
    local sec_of_day = unix_seconds - days * 86400
    local gy, gm, gd = civil_from_civil_days(days)
    local jy, jm, jd = gregorian_to_jalali(gy, gm, gd)
    local hh = math.floor(sec_of_day / 3600)
    local mi = math.floor((sec_of_day % 3600) / 60)
    local ss = math.floor(sec_of_day % 60)
    return { y = jy, m = jm, d = jd, hh = hh, mi = mi, ss = ss }
end

local function jalali_date_str(raw)
    local j = filetime_to_jalali(raw)
    if j == nil then return nil end
    return string.format("%04d-%02d-%02d", j.y, j.m, j.d)
end

local function jalali_datetime_str(raw)
    local j = filetime_to_jalali(raw)
    if j == nil then return nil end
    return string.format("%04d-%02d-%02d %02d:%02d:%02d", j.y, j.m, j.d, j.hh, j.mi, j.ss)
end

-- معکوس gregorian_to_jalali (همان الگوریتم استاندارد ۳۳ساله؛ روی 1405/05/20 <-> 2026-08-11 صحت‌سنجی شد)
local function jalali_to_gregorian(jy, jm, jd)
    jy = jy + 1595
    local days = -355668 + (365 * jy) + (math.floor(jy / 33) * 8) + math.floor(((jy % 33) + 3) / 4) + jd
    if jm < 7 then
        days = days + (jm - 1) * 31
    else
        days = days + ((jm - 7) * 30) + 186
    end

    local gy = 400 * math.floor(days / 146097)
    days = days % 146097
    if days > 36524 then
        days = days - 1
        gy = gy + 100 * math.floor(days / 36524)
        days = days % 36524
        if days >= 365 then days = days + 1 end
    end
    gy = gy + 4 * math.floor(days / 1461)
    days = days % 1461
    if days > 365 then
        gy = gy + math.floor((days - 1) / 365)
        days = (days - 1) % 365
    end
    local gd = days + 1

    local is_leap = (gy % 4 == 0 and gy % 100 ~= 0) or (gy % 400 == 0)
    local g_days_in_month = { 31, is_leap and 29 or 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 }
    local gm = 1
    while gm <= 12 and gd > g_days_in_month[gm] do
        gd = gd - g_days_in_month[gm]
        gm = gm + 1
    end
    return gy, gm, gd
end

-- تاریخ شمسی (سال/ماه/روز عدد) -> تیک FILETIME ابتدای همان روز (UTC) — برای فیلترهای Dropdown شمسی
local function jalali_to_filetime(jy, jm, jd)
    if jy == nil or jm == nil or jd == nil then return nil end
    local gy, gm, gd = jalali_to_gregorian(jy, jm, jd)
    local days = days_from_civil(gy, gm, gd)
    local unix_seconds = days * 86400
    return (unix_seconds + 11644473600) * 10000000
end

-- ============================================================
-- DATABASE HELPERS
-- ============================================================

local function fetch_rows(query, params)
    pcall(function() db.use_db("0000000") end)
    local ok, err = pcall(function()
        db.query({ query = query, params = params or {} })
    end)
    if not ok then return nil, err end
    local rows = {}
    local record = {}
    while db.query_fetch(record) do
        local row = {}
        for i = 1, #record do row[i] = record[i] end
        table.insert(rows, row)
    end
    db.query_free()
    return rows
end

-- ============================================================
-- FILTER PARSER
-- ============================================================

-- فیلتر تاریخ با سه Dropdown شمسی (روز/ماه/سال) پر می‌شود — نه <input type=date> میلادی.
local function jalali_ymd_from_input(input, prefix)
    local y = tonumber(input[prefix .. "_jy"])
    local m = tonumber(input[prefix .. "_jm"])
    local d = tonumber(input[prefix .. "_jd"])
    if y == nil or m == nil or d == nil then return nil, nil, nil end
    return y, m, d
end

local function parse_filters(input)
    input = input or {}

    local from_jy, from_jm, from_jd = jalali_ymd_from_input(input, "from")
    local to_jy, to_jm, to_jd = jalali_ymd_from_input(input, "to")

    local from_raw = jalali_to_filetime(from_jy, from_jm, from_jd)
    local to_raw = jalali_to_filetime(to_jy, to_jm, to_jd)

    local filters = {
        from_raw = from_raw,
        to_raw = to_raw,
        from_jy = from_jy, from_jm = from_jm, from_jd = from_jd,
        to_jy = to_jy, to_jm = to_jm, to_jd = to_jd,
        section_id = tonumber(input["section_id"]),
        workflow_id = tonumber(input["workflow_id"]),
        author_id = tonumber(input["author_id"]),
        responsible_id = tonumber(input["responsible_id"]),
        status = safe_str(input["status"], "all"),
        age_min = tonumber(input["age_min"]),
        age_max = tonumber(input["age_max"]),
    }
    return filters
end

-- می‌سازد: {where_sql, params} بر اساس فیلترها — روی todo_task (tt) و todo_category (tc)
-- استفاده مشترک در Action Query و Stage-Count Query تا فیلتر همیشه یکسان اعمال شود
local function build_action_where(filters, now_raw)
    local clauses = {}
    local params = {}

    local from_raw = filters.from_raw
    local to_raw = filters.to_raw or now_raw

    if from_raw == nil then
        -- پیش‌فرض: DEFAULT_RANGE_DAYS روز قبل از now
        from_raw = now_raw - (CONFIG.DEFAULT_RANGE_DAYS * CONFIG.DAY_TICKS)
    end

    table.insert(clauses, "tt.T_START_DATE >= ?")
    table.insert(params, from_raw)
    table.insert(clauses, "tt.T_START_DATE <= ?")
    table.insert(params, to_raw)

    if filters.section_id then
        table.insert(clauses, "tc.SECTION_ID = ?")
        table.insert(params, filters.section_id)
    end
    if filters.workflow_id then
        table.insert(clauses, "tt.WORK_FLOW_ID = ?")
        table.insert(params, filters.workflow_id)
    end
    if filters.author_id then
        table.insert(clauses, "tt.AUTHOR_ID = ?")
        table.insert(params, filters.author_id)
    end
    if filters.responsible_id then
        -- «مسئول مرحله» ویژگی خودِ Action نیست؛ یعنی حداقل یک مرحلهٔ پیش‌نویس/جاری این اقدام به این فرد سپرده شده
        table.insert(clauses, "EXISTS (SELECT 1 FROM todo_task_steps tts_f WHERE tts_f.TASK_ID = tt.ID AND tts_f.STATUS = 0 AND tts_f.RESPONSIBLE_ID = ?)")
        table.insert(params, filters.responsible_id)
    end
    if filters.status == "open" then
        table.insert(clauses, "tt.STATUS = 1")
    elseif filters.status == "closed" then
        table.insert(clauses, "tt.STATUS = 2")
    end

    return table.concat(clauses, " AND "), params, from_raw, to_raw
end

-- ============================================================
-- ACTION DATA
-- ============================================================

local function fetch_now_raw()
    local rows, err = fetch_rows("SELECT (UNIX_TIMESTAMP() + 11644473600) * 10000000 AS now_raw", {})
    if rows == nil or rows[1] == nil then
        error("خطا در دریافت زمان جاری سرور: " .. tostring(err))
    end
    return tonumber(rows[1][1])
end

local function fetch_actions(where_sql, params)
    local query = [[
SELECT
    tt.ID,
    tt.AUTHOR_ID,
    COALESCE(pm_a.fullname, 'نامشخص') AS author_name,
    tt.CATEGORY_ID,
    COALESCE(tc.CATEGORY_TITLE, 'بدون رده') AS category_title,
    tc.SECTION_ID,
    COALESCE(ts_sec.SECTION_NAME, 'بدون واحد') AS section_name,
    tt.TOPIC_ID,
    COALESCE(tp.NAME, 'سایر') AS topic_name,
    tt.WORK_FLOW_ID,
    COALESCE(tw.WF_TITLE, 'بدون جریان‌کار') AS wf_title,
    tt.TASK_TITLE,
    tt.STATUS,
    tt.T_START_DATE,
    tt.T_REAL_END_DATE
FROM todo_task tt
LEFT JOIN profile_main pm_a ON pm_a.id = tt.AUTHOR_ID
LEFT JOIN todo_category tc ON tc.ID = tt.CATEGORY_ID
LEFT JOIN todo_section ts_sec ON ts_sec.ID = tc.SECTION_ID
LEFT JOIN todo_topic tp ON tp.ID = tt.TOPIC_ID
LEFT JOIN todo_workflow tw ON tw.ID = tt.WORK_FLOW_ID
WHERE ]] .. where_sql .. [[ ORDER BY tt.ID DESC
]]

    local rows, err = fetch_rows(query, params)
    if rows == nil then
        error("خطا در اجرای پرس‌وجوی اقدام‌ها: " .. tostring(err))
    end

    local actions = {}
    for _, r in ipairs(rows) do
        local t_start_date = tonumber(r[14]) or 0
        table.insert(actions, {
            id = tonumber(r[1]),
            author_id = tonumber(r[2]),
            author_name = r[3],
            category_id = tonumber(r[4]),
            category_title = r[5],
            section_id = tonumber(r[6]),
            section_name = r[7],
            topic_id = tonumber(r[8]),
            topic_name = r[9],
            workflow_id = tonumber(r[10]),
            wf_title = r[11],
            task_title = r[12],
            status = tonumber(r[13]),
            t_start_date = t_start_date,
            t_real_end_date = tonumber(r[15]) or 0,
            start_jdate = jalali_date_str(t_start_date),
            start_jdatetime = jalali_datetime_str(t_start_date),
        })
    end
    return actions
end

-- ============================================================
-- STAGE DATA
-- ============================================================

-- تعداد کل مراحل هر اقدام (همهٔ وضعیت‌ها) — برای میانگین/حداکثر تعداد مرحله
local function fetch_step_counts(where_sql, params)
    local query = [[
SELECT tts.TASK_ID, COUNT(*) AS step_count
FROM todo_task_steps tts
JOIN todo_task tt ON tt.ID = tts.TASK_ID
LEFT JOIN todo_category tc ON tc.ID = tt.CATEGORY_ID
WHERE ]] .. where_sql .. [[ GROUP BY tts.TASK_ID
]]
    local rows, err = fetch_rows(query, params)
    if rows == nil then
        error("خطا در اجرای پرس‌وجوی تعداد مراحل: " .. tostring(err))
    end
    local counts = {}
    for _, r in ipairs(rows) do
        counts[tonumber(r[1])] = tonumber(r[2]) or 0
    end
    return counts
end

-- مراحل «پیش‌نویس/جاری» (STATUS=0) فقط برای اقدام‌های باز — مبنای Bottleneck و Responsible
local function fetch_pending_steps(where_sql, params)
    local query = [[
SELECT
    tts.TASK_ID,
    tts.ID AS step_row_id,
    ts.step_name,
    tts.RESPONSIBLE_ID,
    COALESCE(pm_r.fullname, 'نامشخص') AS responsible_name,
    tts.DATE_CREATE,
    tts.DATE_MODIFY
FROM todo_task_steps tts
JOIN todo_task tt ON tt.ID = tts.TASK_ID
LEFT JOIN todo_category tc ON tc.ID = tt.CATEGORY_ID
JOIN todo_step ts ON ts.id = tts.STEP_ID
LEFT JOIN profile_main pm_r ON pm_r.id = tts.RESPONSIBLE_ID
WHERE tts.STATUS = 0
  AND tt.STATUS = 1
  AND ]] .. where_sql .. [[ ORDER BY tts.TASK_ID, tts.DATE_CREATE
]]
    local rows, err = fetch_rows(query, params)
    if rows == nil then
        error("خطا در اجرای پرس‌وجوی مراحل معطل: " .. tostring(err))
    end

    -- یک اقدام باز معمولاً یک مرحلهٔ پیش‌نویس دارد؛ اگر بیش از یکی بود (شاخهٔ موازی)
    -- فقط زودترین‌شروع‌شده را به‌عنوان «مرحلهٔ جاری» نگه می‌داریم تا در Bottleneck دوبار شمرده نشود.
    local by_task = {}
    for _, r in ipairs(rows) do
        local task_id = tonumber(r[1])
        local step = {
            task_id = task_id,
            step_row_id = tonumber(r[2]),
            step_name = r[3],
            responsible_id = tonumber(r[4]),
            responsible_name = r[5],
            date_create = tonumber(r[6]) or 0,
            date_modify = tonumber(r[7]) or 0,
        }
        local existing = by_task[task_id]
        if existing == nil or step.date_create < existing.date_create then
            by_task[task_id] = step
        end
    end

    local current_steps = {}
    for _, step in pairs(by_task) do
        table.insert(current_steps, step)
    end
    return current_steps
end

-- ============================================================
-- KPI CALCULATION
-- ============================================================

local function median(sorted_list)
    local n = #sorted_list
    if n == 0 then return nil end
    if n % 2 == 1 then
        return sorted_list[math.ceil(n / 2)]
    end
    return (sorted_list[n / 2] + sorted_list[n / 2 + 1]) / 2
end

local function compute_kpi(actions, step_counts, now_raw)
    local total = #actions
    local open_n, closed_n = 0, 0
    local lifecycle_days, age_days = {}, {}
    local open_over_30, open_over_60 = 0, 0
    local stage_counts = {}

    for _, a in ipairs(actions) do
        local sc = step_counts[a.id] or 0
        table.insert(stage_counts, sc)

        if a.status == 2 then
            closed_n = closed_n + 1
            if a.t_real_end_date > 0 and a.t_start_date > 0 then
                local d = (a.t_real_end_date - a.t_start_date) / CONFIG.DAY_TICKS
                if d >= 0 then table.insert(lifecycle_days, d) end
            end
        else
            open_n = open_n + 1
            if a.t_start_date > 0 then
                local d = (now_raw - a.t_start_date) / CONFIG.DAY_TICKS
                if d >= 0 then
                    table.insert(age_days, d)
                    if d > CONFIG.RISK.open_over_days_1 then open_over_30 = open_over_30 + 1 end
                    if d > CONFIG.RISK.open_over_days_2 then open_over_60 = open_over_60 + 1 end
                end
            end
        end
    end

    local function avg(list)
        if #list == 0 then return nil end
        local s = 0
        for _, v in ipairs(list) do s = s + v end
        return s / #list
    end

    table.sort(lifecycle_days)
    table.sort(age_days)
    table.sort(stage_counts)

    local total_stages = 0
    local max_stages = 0
    for _, sc in ipairs(stage_counts) do
        total_stages = total_stages + sc
        if sc > max_stages then max_stages = sc end
    end

    return {
        total_actions = total,
        total_stages = total_stages,
        open = open_n,
        closed = closed_n,
        open_pct = fmt_pct(open_n, total),
        avg_lifecycle_closed = avg(lifecycle_days),
        median_lifecycle_closed = median(lifecycle_days),
        avg_age_open = avg(age_days),
        median_age_open = median(age_days),
        open_over_30d = open_over_30,
        open_over_60d = open_over_60,
        avg_stages = (total > 0) and (total_stages / total) or 0,
        max_stages = max_stages,
    }
end

-- ============================================================
-- MONTHLY ANALYSIS
-- ============================================================

local function jalali_month_key(jdate_str)
    if jdate_str == nil then return nil end
    local y, m = jdate_str:match("^(%d+)-(%d+)-%d+$")
    if y == nil then return nil end
    return y .. "-" .. m, tonumber(m), y
end

-- برچسب شامل سال (۲ رقم آخر) تا اگر بازهٔ فیلتر بیش از ۱۲ ماه باشد، ماه‌های هم‌نام سال‌های
-- مختلف (مثلاً دی ۱۴۰۴ و دی ۱۴۰۵) با هم در یک Bucket ادغام نشوند.
local function jalali_month_label(m, y)
    local idx = tonumber(m)
    local month_name = (idx and idx >= 1 and idx <= 12) and CONFIG.PERSIAN_MONTHS[idx] or "؟"
    local yy = tostring(y or ""):sub(-2)
    if yy == "" then return month_name end
    return month_name .. " " .. yy
end

local function compute_monthly(actions, now_raw)
    -- «ماه ایجاد» از start_jdate (محاسبه‌شدهٔ Lua، هنگام Fetch). «ماه بسته‌شدن» جدا در compute_closed_monthly
    -- از همان t_real_end_date موجود در حافظه محاسبه می‌شود — بدون هیچ Query یا وابستگی SQL اضافه.
    local months_order = {}
    local months_set = {}
    local new_by_month = {}

    for _, a in ipairs(actions) do
        local key, m, y = jalali_month_key(a.start_jdate)
        if key ~= nil then
            if not months_set[key] then
                months_set[key] = true
                table.insert(months_order, { key = key, m = m, y = y, label = jalali_month_label(m, y) })
            end
            new_by_month[key] = (new_by_month[key] or 0) + 1
        end
    end

    table.sort(months_order, function(x, y) return x.key < y.key end)

    return months_order, new_by_month
end

local function compute_closed_monthly(actions)
    -- t_real_end_date از همان Fetch اصلی (actions) در حافظه موجود است — نیازی به Query جدا نیست
    local closed_by_month = {}
    for _, a in ipairs(actions) do
        if a.status == 2 and a.t_real_end_date > 0 then
            local key = jalali_month_key(jalali_date_str(a.t_real_end_date))
            if key ~= nil then
                closed_by_month[key] = (closed_by_month[key] or 0) + 1
            end
        end
    end
    return closed_by_month
end

-- ============================================================
-- AGING ANALYSIS
-- ============================================================

local function compute_aging(actions, now_raw)
    local buckets = {}
    for _, b in ipairs(CONFIG.AGE_BUCKETS) do
        table.insert(buckets, { label = b.label, max_days = b.max_days, count = 0 })
    end

    local open_count = 0
    for _, a in ipairs(actions) do
        if a.status ~= 2 and a.t_start_date > 0 then
            local age = (now_raw - a.t_start_date) / CONFIG.DAY_TICKS
            if age >= 0 then
                open_count = open_count + 1
                for _, bucket in ipairs(buckets) do
                    if age <= bucket.max_days then
                        bucket.count = bucket.count + 1
                        break
                    end
                end
            end
        end
    end

    for _, bucket in ipairs(buckets) do
        bucket.pct = fmt_pct(bucket.count, open_count)
    end

    return buckets
end

-- ============================================================
-- DEPARTMENT ANALYSIS
-- ============================================================

local function compute_departments(actions, now_raw)
    local by_section = {}
    local order = {}

    for _, a in ipairs(actions) do
        local key = a.section_name
        local d = by_section[key]
        if d == nil then
            d = {
                name = key, count = 0, open_n = 0, closed_n = 0,
                age_sum = 0, age_n = 0, lifecycle_sum = 0, lifecycle_n = 0,
            }
            by_section[key] = d
            table.insert(order, key)
        end
        d.count = d.count + 1
        if a.status == 2 then
            d.closed_n = d.closed_n + 1
            if a.t_real_end_date > 0 and a.t_start_date > 0 then
                local dd = (a.t_real_end_date - a.t_start_date) / CONFIG.DAY_TICKS
                if dd >= 0 then
                    d.lifecycle_sum = d.lifecycle_sum + dd
                    d.lifecycle_n = d.lifecycle_n + 1
                end
            end
        else
            d.open_n = d.open_n + 1
            if a.t_start_date > 0 then
                local dd = (now_raw - a.t_start_date) / CONFIG.DAY_TICKS
                if dd >= 0 then
                    d.age_sum = d.age_sum + dd
                    d.age_n = d.age_n + 1
                end
            end
        end
    end

    table.sort(order, function(x, y) return by_section[x].count > by_section[y].count end)

    local departments = {}
    for _, key in ipairs(order) do
        local d = by_section[key]
        local open_pct = fmt_pct(d.open_n, d.count)
        local avg_age_open = (d.age_n > 0) and (d.age_sum / d.age_n) or nil
        local avg_lifecycle_closed = (d.lifecycle_n > 0) and (d.lifecycle_sum / d.lifecycle_n) or nil
        local risk_score = open_pct + (avg_age_open or 0)
        local risk_level = "ok"
        if risk_score > CONFIG.RISK.dept_risk_score_crit then
            risk_level = "crit"
        elseif risk_score > CONFIG.RISK.dept_risk_score_warn then
            risk_level = "warn"
        end
        table.insert(departments, {
            name = d.name, count = d.count, open_n = d.open_n, closed_n = d.closed_n,
            open_pct = open_pct, avg_age_open = avg_age_open,
            avg_lifecycle_closed = avg_lifecycle_closed, risk_level = risk_level,
        })
    end
    return departments
end

-- ============================================================
-- WORKFLOW ANALYSIS
-- ============================================================

local function compute_workflows(actions, now_raw)
    local by_wf = {}
    local order = {}

    for _, a in ipairs(actions) do
        local key = a.wf_title
        local w = by_wf[key]
        if w == nil then
            w = { name = key, count = 0, open_n = 0, age_sum = 0, age_n = 0 }
            by_wf[key] = w
            table.insert(order, key)
        end
        w.count = w.count + 1
        if a.status ~= 2 then
            w.open_n = w.open_n + 1
            if a.t_start_date > 0 then
                local dd = (now_raw - a.t_start_date) / CONFIG.DAY_TICKS
                if dd >= 0 then
                    w.age_sum = w.age_sum + dd
                    w.age_n = w.age_n + 1
                end
            end
        end
    end

    table.sort(order, function(x, y) return by_wf[x].count > by_wf[y].count end)

    local workflows = {}
    for _, key in ipairs(order) do
        local w = by_wf[key]
        table.insert(workflows, {
            name = w.name, count = w.count,
            open_pct = fmt_pct(w.open_n, w.count),
            avg_age_open = (w.age_n > 0) and (w.age_sum / w.age_n) or nil,
        })
    end
    return workflows
end

-- ============================================================
-- BOTTLENECK ANALYSIS
-- ============================================================

local function compute_bottlenecks(current_steps, now_raw)
    local by_step = {}
    local order = {}

    for _, s in ipairs(current_steps) do
        local key = s.step_name or "بدون نام"
        local b = by_step[key]
        if b == nil then
            b = { name = key, count = 0, age_sum = 0, max_age = 0, responsibles = {}, responsibles_order = {} }
            by_step[key] = b
            table.insert(order, key)
        end
        b.count = b.count + 1
        local start_ts = s.date_create
        if s.date_modify and s.date_modify > s.date_create then start_ts = s.date_modify end
        local age = (now_raw - start_ts) / CONFIG.DAY_TICKS
        if age < 0 then age = 0 end
        b.age_sum = b.age_sum + age
        if age > b.max_age then b.max_age = age end
        if not b.responsibles[s.responsible_name] then
            b.responsibles[s.responsible_name] = true
            table.insert(b.responsibles_order, s.responsible_name)
        end
    end

    table.sort(order, function(x, y) return by_step[x].count > by_step[y].count end)

    local bottlenecks = {}
    for _, key in ipairs(order) do
        local b = by_step[key]
        table.insert(bottlenecks, {
            name = b.name, count = b.count,
            avg_age = b.age_sum / b.count, max_age = b.max_age,
            responsibles = b.responsibles_order,
        })
    end
    return bottlenecks
end

-- ============================================================
-- AUTHOR ANALYSIS
-- ============================================================

local function compute_authors(actions)
    local by_author = {}
    local order = {}
    local total = #actions

    for _, a in ipairs(actions) do
        local key = a.author_name
        local au = by_author[key]
        if au == nil then
            au = { name = key, count = 0, open_n = 0 }
            by_author[key] = au
            table.insert(order, key)
        end
        au.count = au.count + 1
        if a.status ~= 2 then au.open_n = au.open_n + 1 end
    end

    table.sort(order, function(x, y) return by_author[x].count > by_author[y].count end)

    local authors = {}
    local top1, top3, top5 = 0, 0, 0
    for i, key in ipairs(order) do
        local au = by_author[key]
        if i == 1 then top1 = au.count end
        if i <= 3 then top3 = top3 + au.count end
        if i <= 5 then top5 = top5 + au.count end
        table.insert(authors, {
            name = au.name, count = au.count,
            share = fmt_pct(au.count, total),
            open_pct = fmt_pct(au.open_n, au.count),
        })
    end

    local bus_factor = {
        top1_share = fmt_pct(top1, total),
        top3_share = fmt_pct(top3, total),
        top5_share = fmt_pct(top5, total),
    }

    return authors, bus_factor
end

-- ============================================================
-- RESPONSIBLE ANALYSIS
-- ============================================================

local function compute_responsibles(current_steps, now_raw)
    local by_resp = {}
    local order = {}
    local total = #current_steps

    for _, s in ipairs(current_steps) do
        local key = s.responsible_name
        local r = by_resp[key]
        if r == nil then
            r = { name = key, count = 0, age_sum = 0, max_age = 0 }
            by_resp[key] = r
            table.insert(order, key)
        end
        r.count = r.count + 1
        local start_ts = s.date_create
        if s.date_modify and s.date_modify > s.date_create then start_ts = s.date_modify end
        local age = (now_raw - start_ts) / CONFIG.DAY_TICKS
        if age < 0 then age = 0 end
        r.age_sum = r.age_sum + age
        if age > r.max_age then r.max_age = age end
    end

    table.sort(order, function(x, y) return by_resp[x].count > by_resp[y].count end)

    local responsibles = {}
    local top1, top3, top5 = 0, 0, 0
    for i, key in ipairs(order) do
        local r = by_resp[key]
        if i == 1 then top1 = r.count end
        if i <= 3 then top3 = top3 + r.count end
        if i <= 5 then top5 = top5 + r.count end
        local avg_age = r.age_sum / r.count
        local risk_level = "ok"
        if avg_age > CONFIG.RISK.responsible_age_crit then
            risk_level = "crit"
        elseif avg_age > CONFIG.RISK.responsible_age_warn then
            risk_level = "warn"
        end
        table.insert(responsibles, {
            name = r.name, count = r.count, avg_age = avg_age, max_age = r.max_age,
            risk_level = risk_level,
        })
    end

    local bus_factor = {
        top1_share = fmt_pct(top1, total),
        top3_share = fmt_pct(top3, total),
        top5_share = fmt_pct(top5, total),
    }

    return responsibles, bus_factor
end

-- ============================================================
-- HIERARCHY BUILDER (Treemap + Node-Link Tree)
-- ============================================================

local function compute_hierarchy(actions)
    -- بخش (todo_section) -> رده (todo_category) -> موضوع (todo_topic) -> تعداد
    local sections = {}
    local sections_order = {}

    for _, a in ipairs(actions) do
        local sname = a.section_name
        local sec = sections[sname]
        if sec == nil then
            sec = { name = sname, categories = {}, cat_order = {} }
            sections[sname] = sec
            table.insert(sections_order, sname)
        end

        local cname = a.category_title
        local cat = sec.categories[cname]
        if cat == nil then
            cat = { name = cname, topics = {}, topic_order = {} }
            sec.categories[cname] = cat
            table.insert(sec.cat_order, cname)
        end

        local tname = a.topic_name
        cat.topics[tname] = (cat.topics[tname] or 0) + 1
        if cat.topics[tname] == 1 then
            table.insert(cat.topic_order, tname)
        end
    end

    table.sort(sections_order)

    local hier = { name = "کل سازمان", children = {} }
    for _, sname in ipairs(sections_order) do
        local sec = sections[sname]
        local sec_node = { name = sname, children = {} }
        for _, cname in ipairs(sec.cat_order) do
            local cat = sec.categories[cname]
            local cat_node = { name = cname, children = {} }
            for _, tname in ipairs(cat.topic_order) do
                table.insert(cat_node.children, { name = tname, value = cat.topics[tname] })
            end
            table.insert(sec_node.children, cat_node)
        end
        table.insert(hier.children, sec_node)
    end

    return hier
end

-- ============================================================
-- INSIGHTS (Rule-based)
-- ============================================================

local function build_insights(kpi, departments, bottlenecks, authors, bus_author, responsibles)
    local insights = {}

    if kpi.open_pct > 70 then
        table.insert(insights, {
            cls = "crit", mark = "▲",
            html = "<b>انباشت صف:</b> " .. fmt_num(kpi.open) .. " اقدام از " .. fmt_num(kpi.total_actions) ..
                " مورد (" .. fmt_dec1(kpi.open_pct) .. "٪) هنوز باز است؛ " .. fmt_num(kpi.open_over_60d) ..
                " مورد بیش از ۶۰ روز بدون تغییر مانده.",
        })
    end

    for _, d in ipairs(departments) do
        if d.risk_level == "crit" and d.count >= 5 then
            table.insert(insights, {
                cls = "crit", mark = "▲",
                html = "<b>واحد پرریسک — " .. escape_html(d.name) .. ":</b> از " .. fmt_num(d.count) ..
                    " اقدام، " .. fmt_dec1(d.open_pct) .. "٪ باز است" ..
                    (d.avg_age_open and (" با میانگین سکون " .. fmt_dec1(d.avg_age_open) .. " روز") or "") .. ".",
            })
        end
    end

    if #bottlenecks > 0 then
        local top = bottlenecks[1]
        if top.count >= 5 then
            table.insert(insights, {
                cls = "warn", mark = "●",
                html = "<b>گلوگاه اصلی:</b> مرحلهٔ «" .. escape_html(top.name) .. "» با " .. fmt_num(top.count) ..
                    " اقدام معطل و میانگین سکون " .. fmt_dec1(top.avg_age) .. " روز، بیشترین تجمع را دارد.",
            })
        end
    end

    if bus_author and bus_author.top1_share > CONFIG.RISK.author_share_concentration_pct and #authors > 0 then
        table.insert(insights, {
            cls = "warn", mark = "●",
            html = "<b>تمرکز مولف:</b> " .. fmt_dec1(bus_author.top1_share) .. "٪ از کل اقدام‌ها فقط توسط «" ..
                escape_html(authors[1].name) .. "» ثبت شده — ریسک تک‌نقطه‌ای در ثبت اقدام.",
        })
    end

    local crit_resp = {}
    for _, r in ipairs(responsibles) do
        if r.risk_level == "crit" then table.insert(crit_resp, r.name) end
        if #crit_resp >= 3 then break end
    end
    if #crit_resp > 0 then
        table.insert(insights, {
            cls = "warn", mark = "●",
            html = "<b>ریسک مسئولان:</b> " .. escape_html(table.concat(crit_resp, "، ")) ..
                " میانگین سکون بیش از " .. fmt_num(CONFIG.RISK.responsible_age_crit) .. " روز در پرونده‌های تحت مسئولیت خود دارند.",
        })
    end

    -- نکتهٔ مثبت: واحدی با حجم بالا و lifecycle کوتاه
    local best = nil
    for _, d in ipairs(departments) do
        if d.count >= 10 and d.avg_lifecycle_closed ~= nil then
            if best == nil or d.avg_lifecycle_closed < best.avg_lifecycle_closed then
                best = d
            end
        end
    end
    if best ~= nil then
        table.insert(insights, {
            cls = "info", mark = "i",
            html = "<b>نکتهٔ مثبت:</b> واحد «" .. escape_html(best.name) .. "» با وجود حجم قابل توجه، میانگین زمان بسته‌شدن پرونده‌ها تنها " ..
                fmt_dec1(best.avg_lifecycle_closed) .. " روز است.",
        })
    end

    return insights
end

-- ============================================================
-- FILTER OPTIONS (برای Dropdownهای فیلتر — مستقل از بازهٔ تاریخ، برای تجربهٔ پایدار)
-- ============================================================

local function fetch_filter_options()
    local sections, err1 = fetch_rows(
        "SELECT ID, SECTION_NAME FROM todo_section ORDER BY SECTION_NAME", {})
    local workflows, err2 = fetch_rows(
        "SELECT ID, WF_TITLE FROM todo_workflow WHERE COALESCE(WF_DISABLED,0)=0 ORDER BY WF_TITLE", {})
    -- فقط افرادی که همین الان حداقل یک مرحلهٔ پیش‌نویس/جاری به‌عهده دارند — فهرست کوتاه‌تر و مرتبط‌تر از کل profile_main
    local responsibles, err3 = fetch_rows([[
        SELECT DISTINCT tts.RESPONSIBLE_ID, pm.fullname
        FROM todo_task_steps tts
        JOIN profile_main pm ON pm.id = tts.RESPONSIBLE_ID
        WHERE tts.STATUS = 0
        ORDER BY pm.fullname
    ]], {})

    if sections == nil then error("خطا در دریافت فهرست واحدها: " .. tostring(err1)) end
    if workflows == nil then error("خطا در دریافت فهرست جریان‌های کاری: " .. tostring(err2)) end
    if responsibles == nil then error("خطا در دریافت فهرست مسئولان: " .. tostring(err3)) end

    return sections, workflows, responsibles
end

-- فهرست مولفان از خودِ داده فعلی (actions) ساخته می‌شود — بدون Query اضافه

-- ============================================================
-- JSON BUILDER
-- ============================================================

local function build_dashboard_json(ctx)
    local kpi = ctx.kpi
    local months_order, new_by_month = ctx.months_order, ctx.new_by_month
    local closed_by_month = ctx.closed_by_month

    local monthly_new, monthly_closed = {}, {}
    local cum_months, cum_new, cum_closed, cum_backlog = {}, {}, {}, {}
    local running_new, running_closed = 0, 0

    for _, mo in ipairs(months_order) do
        local n = new_by_month[mo.key] or 0
        local c = closed_by_month[mo.key] or 0
        monthly_new[mo.label] = n
        monthly_closed[mo.label] = c
        running_new = running_new + n
        running_closed = running_closed + c
        table.insert(cum_months, mo.label)
        table.insert(cum_new, running_new)
        table.insert(cum_closed, running_closed)
        table.insert(cum_backlog, running_new - running_closed)
    end

    local age_labels, age_values = {}, {}
    for _, b in ipairs(ctx.aging) do
        table.insert(age_labels, b.label)
        table.insert(age_values, b.count)
    end

    local status_action_pie = {
        { name = "باز", value = kpi.open },
        { name = "بسته شده", value = kpi.closed },
    }

    local top_workflows = {}
    for i, w in ipairs(ctx.workflows) do
        if i > CONFIG.TOP_N_WORKFLOWS then break end
        table.insert(top_workflows, w)
    end

    local top_bottlenecks = {}
    for i, b in ipairs(ctx.bottlenecks) do
        if i > CONFIG.TOP_N_BOTTLENECKS then break end
        table.insert(top_bottlenecks, { name = b.name, count = b.count, avg_age = b.avg_age, max_age = b.max_age })
    end

    local data = {
        kpi = {
            total_actions = kpi.total_actions,
            total_stages = kpi.total_stages,
            open = kpi.open,
            closed = kpi.closed,
            open_pct = kpi.open_pct,
            avg_lifecycle_closed = kpi.avg_lifecycle_closed,
            median_lifecycle_closed = kpi.median_lifecycle_closed,
            avg_age_open = kpi.avg_age_open,
            median_age_open = kpi.median_age_open,
            open_over_30d = kpi.open_over_30d,
            open_over_60d = kpi.open_over_60d,
            avg_stages = kpi.avg_stages,
            max_stages = kpi.max_stages,
        },
        monthly = { new = monthly_new, closed = monthly_closed },
        cumulative = { months = cum_months, new = cum_new, closed = cum_closed, backlog = cum_backlog },
        age_buckets = { labels = age_labels, values = age_values },
        departments = ctx.departments,
        authors = ctx.authors,
        author_bus_factor = ctx.bus_author,
        responsible_risk = ctx.responsibles,
        responsible_bus_factor = ctx.bus_responsible,
        workflows = top_workflows,
        status_action_pie = status_action_pie,
        bottleneck_stages = top_bottlenecks,
    }

    return data
end

local function build_detail_rows(actions, now_raw)
    local rows = {}
    for i, a in ipairs(actions) do
        if i > CONFIG.DETAIL_ROWS_LIMIT then break end
        local age_days = nil
        if a.status ~= 2 and a.t_start_date > 0 then
            age_days = (now_raw - a.t_start_date) / CONFIG.DAY_TICKS
        end
        table.insert(rows, {
            id = a.id,
            title = a.task_title,
            section = a.section_name,
            category = a.category_title,
            workflow = a.wf_title,
            author = a.author_name,
            status = (a.status == 2) and "بسته شده" or "باز",
            start_date = a.start_jdate,
            age_days = age_days,
        })
    end
    return rows
end

