local function render_hero_pills(kpi)
    local parts = {}
    table.insert(parts, '<div class="pill accent"><div class="n">' .. fmt_num(kpi.total_actions) .. '</div><div class="l">کل اقدام‌ها</div></div>')
    table.insert(parts, '<div class="pill"><div class="n">' .. fmt_num(kpi.open) .. ' (' .. fmt_dec1(kpi.open_pct) .. '٪)</div><div class="l">باز</div></div>')
    table.insert(parts, '<div class="pill"><div class="n">' .. fmt_num(kpi.closed) .. '</div><div class="l">بسته‌شده</div></div>')
    table.insert(parts, '<div class="pill"><div class="n">' .. fmt_num(kpi.open_over_60d) .. '</div><div class="l">راکد بیش از ۶۰ روز</div></div>')
    return table.concat(parts, "\n")
end

local function render_kpi_cards(kpi)
    local cards = {
        { tag = "حجم فرآیند", val = fmt_num(kpi.total_stages),
          cap = "مرحلهٔ ثبت‌شده در " .. fmt_num(kpi.total_actions) .. " اقدام" },
        { tag = "نرخ باز بودن", val = fmt_dec1(kpi.open_pct) .. "٪",
          cap = fmt_num(kpi.open) .. " اقدام هنوز باز است" },
        { tag = "میانگین زمان تا بسته‌شدن", val = (kpi.avg_lifecycle_closed and (fmt_dec1(kpi.avg_lifecycle_closed) .. " روز") or "—"),
          cap = "میانه: " .. (kpi.median_lifecycle_closed and (fmt_dec1(kpi.median_lifecycle_closed) .. " روز") or "—") },
        { tag = "میانگین سکون اقدام‌های باز", val = (kpi.avg_age_open and (fmt_dec1(kpi.avg_age_open) .. " روز") or "—"),
          cap = fmt_num(kpi.open_over_30d) .. " مورد بیش از ۳۰ روز" },
        { tag = "میانگین/حداکثر تعداد مرحله", val = fmt_dec1(kpi.avg_stages),
          cap = "حداکثر مشاهده‌شده: " .. fmt_num(kpi.max_stages) .. " مرحله" },
    }
    local parts = {}
    for _, c in ipairs(cards) do
        table.insert(parts, '<div class="kpi-card"><div class="tag">' .. c.tag .. '</div><div class="val">' ..
            c.val .. '</div><div class="cap">' .. c.cap .. '</div></div>')
    end
    return table.concat(parts, "\n")
end

local function render_insights_html(insights)
    if #insights == 0 then
        return '<div class="insight info"><div class="mark">i</div><div class="body">در بازهٔ انتخاب‌شده یافتهٔ قابل‌توجهی (بر اساس آستانه‌های تعریف‌شده) شناسایی نشد.</div></div>'
    end
    local parts = {}
    for _, ins in ipairs(insights) do
        table.insert(parts, '<div class="insight ' .. ins.cls .. '"><div class="mark">' .. ins.mark ..
            '</div><div class="body">' .. ins.html .. '</div></div>')
    end
    return table.concat(parts, "\n")
end

