            escape_html(r.start_date) .. '</td><td>' .. (r.age_days and (fmt_dec1(r.age_days) .. ' روز') or '—') .. '</td></tr>')
    end
    if #rows == 0 then rows = { '<tr><td colspan="9">اقدامی در این بازه/فیلتر یافت نشد</td></tr>' } end
