local function render_jalali_date_picker(prefix, label, j, current_jy)
    local d_opts = { "" }
    for i = 1, 31 do table.insert(d_opts, tostring(i)) end
    local m_opts = {}
    for i = 1, 12 do table.insert(m_opts, { v = i, l = CONFIG.PERSIAN_MONTHS[i] }) end

    local function num_opt(v, selected_v)
        local sel = (tonumber(selected_v) == tonumber(v)) and ' selected' or ''
        return '<option value="' .. tostring(v) .. '"' .. sel .. '>' .. tostring(v) .. '</option>'
    end

    local d_html = {}
    for i = 1, 31 do table.insert(d_html, num_opt(i, j.d)) end

    local m_html = {}
    for _, mo in ipairs(m_opts) do
        local sel = (tonumber(j.m) == mo.v) and ' selected' or ''
        table.insert(m_html, '<option value="' .. mo.v .. '"' .. sel .. '>' .. mo.l .. '</option>')
    end

    local y_html = {}
    for y = current_jy - 5, current_jy + 1 do
        table.insert(y_html, num_opt(y, j.y))
    end

    return '<div class="filter-field"><label>' .. label .. '</label><div class="jdate-group">' ..
        '<select name="' .. prefix .. '_jd">' .. table.concat(d_html) .. '</select>' ..
        '<select name="' .. prefix .. '_jm">' .. table.concat(m_html) .. '</select>' ..
        '<select name="' .. prefix .. '_jy">' .. table.concat(y_html) .. '</select>' ..
        '</div></div>'
end

local function render_filter_bar(filters, filter_options, from_j, to_j, current_jy)
    local sections, workflows, responsibles = filter_options.sections, filter_options.workflows, filter_options.responsibles

    local function opt(id, name, selected_id)
        local sel = (tonumber(selected_id) == tonumber(id)) and ' selected' or ''
        return '<option value="' .. tostring(id) .. '"' .. sel .. '>' .. escape_html(name) .. '</option>'
    end

    local section_opts = { '<option value="">همه واحدها</option>' }
    for _, s in ipairs(sections) do
        table.insert(section_opts, opt(s[1], s[2], filters.section_id))
    end

    local workflow_opts = { '<option value="">همه جریان‌های کاری</option>' }
    for _, w in ipairs(workflows) do
        table.insert(workflow_opts, opt(w[1], w[2], filters.workflow_id))
    end

    local responsible_opts = { '<option value="">همه مسئولان مرحله</option>' }
    for _, r in ipairs(responsibles) do
        table.insert(responsible_opts, opt(r[1], r[2], filters.responsible_id))
    end

    local status_opts = {
        { v = "all", l = "همه" }, { v = "open", l = "فقط باز" }, { v = "closed", l = "فقط بسته‌شده" },
    }
    local status_html = {}
    for _, so in ipairs(status_opts) do
        local sel = (filters.status == so.v) and ' selected' or ''
        table.insert(status_html, '<option value="' .. so.v .. '"' .. sel .. '>' .. so.l .. '</option>')
    end

    local from_picker = render_jalali_date_picker("from", "از تاریخ", from_j, current_jy)
    local to_picker = render_jalali_date_picker("to", "تا تاریخ", to_j, current_jy)

    return [[
<form class="filter-bar" id="filterForm" method="POST" action="">
  <div class="filter-grid">
    ]] .. from_picker .. [[
    ]] .. to_picker .. [[
    <div class="filter-field"><label>واحد سازمانی</label><select name="section_id">]] .. table.concat(section_opts) .. [[</select></div>
    <div class="filter-field"><label>جریان‌کاری</label><select name="workflow_id">]] .. table.concat(workflow_opts) .. [[</select></div>
    <div class="filter-field"><label>مسئول مرحلهٔ جاری</label><select name="responsible_id">]] .. table.concat(responsible_opts) .. [[</select></div>
    <div class="filter-field"><label>وضعیت اقدام</label><select name="status">]] .. table.concat(status_html) .. [[</select></div>
  </div>
  <div class="filter-actions">
    <button type="submit" class="btn-filter" id="filterSubmitBtn">اعمال فیلتر</button>
    <button type="button" class="btn-filter reset" onclick="window.location = window.location.pathname">پاک کردن فیلتر</button>
  </div>
</form>
]]
end

