-- توجه: اعداد با ارقام غربی (نه Persian toLocaleString) نمایش داده می‌شوند — چون فونت
-- Peyda (نه PeydaFaNum) استفاده می‌شود و ارقام فارسیِ خروجی toLocaleString با آن هم‌خوان نیست.
local REPORT_JS_BODY = [[
<script>
var DATA = JSON.parse(document.getElementById('dashData').textContent);
var HIER = JSON.parse(document.getElementById('hierData').textContent);

const ACCENT = '#16509D';
const PALETTE = ['#16509D','#3568AC','#5480BB','#7398CB','#93B0DA','#0D3055','#2E4B6B','#9AA7B5','#6C7A89','#B9C3CE'];
const GRAY = '#999';
const LIGHT = '#e5e5e5';

function fa(n){ return Number(n||0).toLocaleString('en-US'); }
function faNum(n){ return Number(n||0).toLocaleString('en-US', {maximumFractionDigits:1}); }

Chart.defaults.font.family = "'PeydaReport', Tahoma, sans-serif";
Chart.defaults.font.size = 13;
Chart.defaults.color = '#666';
Chart.defaults.borderColor = '#ddd';

/* ================= نمودارها (Chart.js) — در initCharts() تا بعد از هر Fetch فیلتر دوباره‌سازی شوند =================
   نمونهٔ هر نمودار در متغیر سطح‌بالا نگه داشته می‌شود؛ هر بار دوباره صدا زدن initCharts ابتدا
   نمونهٔ قبلی را destroy می‌کند (وگرنه Chart.js روی همان Canvas خطای «Canvas is already in use» می‌دهد). */
var trendChartInst, statusPieInst, backlogChartInst, ageChartInst, deptPieInst, workflowChartInst, bottleneckChartInst;

function initCharts(){
  [trendChartInst, statusPieInst, backlogChartInst, ageChartInst, deptPieInst, workflowChartInst, bottleneckChartInst]
    .forEach(function(c){ if (c) { try { c.destroy(); } catch(e) {} } });
  // پوشش اضافه برای Canvasهایی که مستقیماً روی DOM (نه فقط متغیرهای بالا) چارت فعال دارند —
  // مثلاً اگر یک نمونهٔ قبلی به هر دلیلی در متغیرهای initCharts ردیابی نشده باشد.
  ['trendChart','statusPie','backlogChart','ageChart','deptPie','workflowChart','bottleneckChart'].forEach(function(id){
    var existing = Chart.getChart ? Chart.getChart(id) : null;
    if (existing) { try { existing.destroy(); } catch(e) {} }
  });

  var months = Object.keys(DATA.monthly.new);
  trendChartInst = new Chart(document.getElementById('trendChart'), {
    data:{
      labels:months,
      datasets:[
        {type:'bar', label:'اقدام جدید', data:months.map(m=>DATA.monthly.new[m]), backgroundColor:ACCENT, borderRadius:5, order:2},
        {type:'line', label:'اقدام بسته‌شده', data:months.map(m=>DATA.monthly.closed[m]||0), borderColor:GRAY, backgroundColor:GRAY, tension:.3, borderWidth:2.5, pointRadius:4, order:1}
      ]
    },
    options:{ responsive:true, maintainAspectRatio:false,
      plugins:{legend:{position:'top', labels:{boxWidth:12,padding:14}}},
      scales:{ x:{grid:{display:false}}, y:{grid:{color:LIGHT}, beginAtZero:true} } }
  });

  statusPieInst = new Chart(document.getElementById('statusPie'), {
    type:'doughnut',
    data:{ labels: DATA.status_action_pie.map(d=>d.name),
      datasets:[{data: DATA.status_action_pie.map(d=>d.value), backgroundColor:[ACCENT, LIGHT], borderColor:'#fff', borderWidth:3}] },
    options:{ responsive:true, maintainAspectRatio:false, cutout:'65%',
      plugins:{legend:{position:'bottom', labels:{boxWidth:12,padding:14}}} }
  });

  backlogChartInst = new Chart(document.getElementById('backlogChart'), {
    data:{ labels: DATA.cumulative.months,
      datasets:[
        {type:'line', label:'مجموع اقدام‌های بازشده', data:DATA.cumulative.new, borderColor:ACCENT, backgroundColor:ACCENT+'22', fill:true, tension:.3, borderWidth:2.5, pointRadius:3},
        {type:'line', label:'مجموع اقدام‌های بسته‌شده', data:DATA.cumulative.closed, borderColor:GRAY, backgroundColor:GRAY+'22', fill:true, tension:.3, borderWidth:2.5, pointRadius:3},
        {type:'line', label:'صف باز (Backlog)', data:DATA.cumulative.backlog, borderColor:'#000', backgroundColor:'transparent', borderDash:[6,4], tension:.3, borderWidth:2, pointRadius:3}
      ] },
    options:{ responsive:true, maintainAspectRatio:false,
      plugins:{legend:{position:'top', labels:{boxWidth:12,padding:12,font:{size:11}}}},
      scales:{ x:{grid:{display:false}}, y:{grid:{color:LIGHT}, beginAtZero:true} } }
  });

  ageChartInst = new Chart(document.getElementById('ageChart'), {
    type:'bar',
    data:{ labels: DATA.age_buckets.labels,
      datasets:[{label:'تعداد اقدام باز', data: DATA.age_buckets.values,
        backgroundColor:[LIGHT,'#c9d3de','#93B0DA','#3568AC',ACCENT], borderRadius:5}] },
    options:{ responsive:true, maintainAspectRatio:false, plugins:{legend:{display:false}},
      scales:{ x:{grid:{display:false}}, y:{grid:{color:LIGHT}, beginAtZero:true} } }
  });

  deptPieInst = new Chart(document.getElementById('deptPie'), {
    type:'pie',
    data:{ labels: DATA.departments.map(d=>d.name),
      datasets:[{data: DATA.departments.map(d=>d.count), backgroundColor: PALETTE, borderColor:'#fff', borderWidth:2}] },
    options:{ responsive:true, maintainAspectRatio:false,
      plugins:{legend:{position:'bottom', labels:{boxWidth:11,padding:8,font:{size:11}}}} }
  });

  var wf = DATA.workflows;
  workflowChartInst = new Chart(document.getElementById('workflowChart'), {
    data:{ labels: wf.map(d=>d.name.length>22? d.name.slice(0,22)+'…': d.name),
      datasets:[
        {type:'bar', label:'تعداد اقدام', data: wf.map(d=>d.count), backgroundColor:ACCENT, borderRadius:5, yAxisID:'y'},
        {type:'line', label:'درصد باز', data: wf.map(d=>d.open_pct), borderColor:'#000', backgroundColor:'#000', yAxisID:'y1', tension:.3, pointRadius:3}
      ] },
    options:{ responsive:true, maintainAspectRatio:false,
      plugins:{legend:{position:'top', labels:{boxWidth:12,padding:12}}},
      scales:{
        x:{grid:{display:false}, ticks:{font:{size:10}, maxRotation:60, minRotation:40}},
        y:{grid:{color:LIGHT}, beginAtZero:true, position:'left'},
        y1:{beginAtZero:true, max:100, position:'right', grid:{display:false}, ticks:{callback:v=>v+'%'}}
      } }
  });

  var bn = (DATA.bottleneck_stages||[]).slice(0,10);
  bottleneckChartInst = new Chart(document.getElementById('bottleneckChart'), {
    type:'bar',
    data:{ labels: bn.map(d=>d.name.length>26? d.name.slice(0,26)+'…': d.name),
      datasets:[{label:'تعداد معطل', data: bn.map(d=>d.count),
        backgroundColor: bn.map(d=> d.avg_age>30? ACCENT : d.avg_age>10? '#7c8a99' : '#c9d3de'), borderRadius:5}] },
    options:{ indexAxis:'y', responsive:true, maintainAspectRatio:false,
      plugins:{legend:{display:false}, tooltip:{callbacks:{afterLabel:function(ctx){
        var item = bn[ctx.dataIndex];
        return 'میانگین سکون: '+faNum(item.avg_age)+' روز | حداکثر: '+faNum(item.max_age)+' روز';
      }}}},
      scales:{ x:{grid:{color:LIGHT}, beginAtZero:true}, y:{grid:{display:false}, ticks:{font:{size:10.5}}} } }
  });
}

/* ================= TREEMAP (D3) ================= */
var currentRoot, stack, deptColorMap;
const tmContainer = document.getElementById('treemap');
const tmLegend = document.getElementById('tmLegend');

function renderBreadcrumb(){
  const el = document.getElementById('breadcrumb'); el.innerHTML = '';
  stack.forEach((node,i)=>{
    const s = document.createElement('span'); s.className='crumb'; s.textContent = node.name;
    s.onclick = ()=>{ stack = stack.slice(0,i+1); currentRoot = stack[stack.length-1]; drawTreemap(); };
    el.appendChild(s);
    if(i<stack.length-1){ const a=document.createElement('span'); a.textContent='›'; a.style.color='#999'; el.appendChild(a); }
  });
}

function drawTreemap(){
  renderBreadcrumb();
  tmContainer.innerHTML = '';
  const width = tmContainer.clientWidth || 1000, height = 480;
  const root = d3.hierarchy({name:currentRoot.name, children:currentRoot.children||[]})
    .sum(d=>d.value||0).sort((a,b)=>b.value-a.value);
  d3.treemap().size([width,height]).paddingInner(3).paddingOuter(3).round(true)(root);
  const svg = d3.select(tmContainer).append('svg').attr('width',width).attr('height',height).attr('viewBox',[0,0,width,height]);
  const deptName = stack[1] ? stack[1].name : null;
  const baseColor = stack.length===1 ? null : (deptColorMap[deptName] || '#8899aa');
  const nodes = (root.children && root.children.length) ? root.children : [root];
  const hasChildren = d => !!(d.data.children && d.data.children.length);
  const cell = svg.selectAll('g').data(nodes, d=>d.data.name).join('g')
    .attr('transform', d=>'translate('+d.x0+','+d.y0+')')
    .style('cursor', d=>hasChildren(d)?'pointer':'default');
  cell.append('rect').attr('class','tm-node')
    .attr('width', d=>Math.max(0,d.x1-d.x0)).attr('height', d=>Math.max(0,d.y1-d.y0))
    .attr('fill', (d,i)=> stack.length===1 ? (deptColorMap[d.data.name]||PALETTE[i%PALETTE.length]) : baseColor)
    .attr('opacity', d=>0.55+Math.min(0.4,(d.value||1)/(root.value||1)*3))
    .on('click', function(evt,d){ if(hasChildren(d)){ stack.push(d.data); currentRoot=d.data; drawTreemap(); } })
    .append('title').text(d=>d.data.name+': '+d.value+' اقدام'+(hasChildren(d)?' (کلیک برای جزئیات)':''));
  cell.each(function(d){
    const w=d.x1-d.x0, h=d.y1-d.y0; if(w<38||h<24) return;
    const g = d3.select(this);
    const maxChars = Math.max(4, Math.floor(w/7.2));
    g.append('text').attr('class','tm-label').attr('x',8).attr('y',18).attr('font-size',Math.min(13,w/9)).attr('font-weight',700)
      .text(d.data.name.length>maxChars ? d.data.name.slice(0,maxChars)+'…' : d.data.name);
    if(h>40){ g.append('text').attr('class','tm-sub').attr('x',8).attr('y',36).attr('font-size',11)
      .text(d.value+' اقدام'+(hasChildren(d)?' ⤵':'')); }
  });
}
/* ================= NODE-LINK TREE ================= */
var ntTotals, ntCollapsed;
function ntTotal(raw, path){
  let t;
  if(raw.value!=null){ t = raw.value; } else { t=0; (raw.children||[]).forEach(c=>{ t += ntTotal(c, path+'/'+c.name); }); }
  ntTotals.set(path, t); return t;
}

function escXml(s){ return String(s).replace(/&/g,']] .. AMP_ENTITY .. [[').replace(/</g,']] .. LT_ENTITY .. [[').replace(/>/g,']] .. GT_ENTITY .. [[').replace(/"/g,']] .. QUOT_ENTITY .. [['); }
function ntColor(deptName){ return deptColorMap[deptName] || '#8899aa'; }

function drawNodeTree(){
  const el = document.getElementById('nodetree');
  const dx = 28, levelWidth = 240;
  let rowCounter = 0, maxDepth = 0;
  const positioned = [], linkPairs = [];
  function layout(raw, path, depth, deptName){
    maxDepth = Math.max(maxDepth, depth);
    const hasRaw = !!(raw.children && raw.children.length);
    const expanded = hasRaw && !ntCollapsed.has(path);
    const value = ntTotals.get(path) || 0;
    const thisDept = depth===0 ? null : (depth===1 ? raw.name : deptName);
    const node = {name:raw.name, path, depth, value, hasChildren:hasRaw, expanded, deptName:thisDept, row:0};
    positioned.push(node);
    if(expanded){
      const rows=[];
      raw.children.forEach(c=>{ const cp=path+'/'+c.name; const cn=layout(c,cp,depth+1,thisDept); rows.push(cn.row); linkPairs.push({from:node,to:cn}); });
      node.row = (rows[0]+rows[rows.length-1])/2;
    } else { node.row = rowCounter++; }
    return node;
  }
  layout(HIER,'root',0,null);
  const containerWidth = el.clientWidth || 1200;
  const totalWidth = Math.max(containerWidth, (maxDepth+1)*levelWidth+60);
  const totalHeight = Math.max(540, rowCounter*dx+40);
  const screenX = depth => totalWidth-50-depth*levelWidth;
  const screenY = row => row*dx+26;
  let parts = [];
  parts.push('<svg viewBox="0 0 '+totalWidth+' '+totalHeight+'" width="'+totalWidth+'" height="'+totalHeight+'" font-family="PeydaReport,Tahoma,sans-serif" font-size="12">');
  parts.push('<g>');
  linkPairs.forEach(l=>{
    const x1=screenX(l.from.depth), y1=screenY(l.from.row), x2=screenX(l.to.depth), y2=screenY(l.to.row), mx=(x1+x2)/2;
    parts.push('<path class="nt-link" d="M'+x1+','+y1+' C'+mx+','+y1+' '+mx+','+y2+' '+x2+','+y2+'"></path>');
  });
  parts.push('</g><g>');
  positioned.forEach(n=>{
    const x=screenX(n.depth), y=screenY(n.row);
    const color = n.depth===0 ? '#000' : ntColor(n.deptName);
    const radius = n.depth===0 ? 8 : (n.hasChildren ? Math.max(6,Math.min(13,4+Math.sqrt(n.value))) : 4.5);
    const fill = n.hasChildren ? color : '#bbb';
    const anchor = n.hasChildren ? 'end':'start', tx = n.hasChildren?-16:16;
    const fw = n.depth===0?700:n.depth===1?600:400;
    const marker = n.hasChildren ? (n.expanded?' −':' +') : '';
    parts.push('<g class="nt-node" data-path="'+escXml(n.path)+'" transform="translate('+x+','+y+')" style="cursor:'+(n.hasChildren?'pointer':'default')+'">');
    parts.push('<circle r="'+radius+'" fill="'+fill+'" stroke="#fff" stroke-width="2"></circle>');
    parts.push('<text x="'+tx+'" y="0" dy="0.32em" text-anchor="'+anchor+'" font-weight="'+fw+'">'+escXml(n.name)+marker+'</text>');
    parts.push('<text class="count" x="'+tx+'" y="14" text-anchor="'+anchor+'" font-size="10.5">'+n.value+' اقدام</text></g>');
  });
  parts.push('</g></svg>');
  el.innerHTML = parts.join('');
  el.querySelectorAll('.nt-node').forEach(g=>{
    const path = g.getAttribute('data-path');
    g.addEventListener('click', ()=>{ if(ntCollapsed.has(path)) ntCollapsed.delete(path); else ntCollapsed.add(path); drawNodeTree(); });
  });
}
window.addEventListener('resize', ()=>drawNodeTree());

/* ================= RISK MATRIX (D3) ================= */
function drawRiskMatrix(){
  const el = document.getElementById('riskmatrix'); el.innerHTML='';
  const width = el.clientWidth || 600, height=400, margin={top:20,right:30,bottom:50,left:50};
  const depts = DATA.departments.filter(d=>d.avg_age_open!=null);
  if(depts.length===0){ el.innerHTML = '<p style="color:#666;padding:20px;">داده‌ای برای نمایش نیست</p>'; return; }
  const maxAge = d3.max(depts,d=>d.avg_age_open)*1.15 || 10;
  const maxCount = d3.max(depts,d=>d.count) || 1;
  const svg = d3.select(el).append('svg').attr('width',width).attr('height',height);
  const x = d3.scaleLinear().domain([0,100]).range([margin.left,width-margin.right]);
  const y = d3.scaleLinear().domain([0,maxAge]).range([height-margin.bottom,margin.top]);
  const r = d3.scaleSqrt().domain([0,maxCount]).range([7,38]);
  svg.append('rect').attr('x',x(60)).attr('y',margin.top).attr('width',x(100)-x(60)).attr('height',y(0)-margin.top).attr('fill',ACCENT).attr('opacity',0.06);
  svg.append('g').attr('transform','translate(0,'+(height-margin.bottom)+')').call(d3.axisBottom(x).ticks(5).tickFormat(d=>d+'%'))
    .call(g=>{ g.selectAll('text').attr('fill','#666').attr('font-size',10.5); g.selectAll('path,line').attr('stroke','#ddd'); });
  svg.append('g').attr('transform','translate('+margin.left+',0)').call(d3.axisLeft(y).ticks(5))
    .call(g=>{ g.selectAll('text').attr('fill','#666').attr('font-size',10.5); g.selectAll('path,line').attr('stroke','#ddd'); });
  svg.append('text').attr('x',width/2).attr('y',height-8).attr('text-anchor','middle').attr('fill','#666').attr('font-size',11).text('درصد اقدام‌های باز →');
  svg.append('text').attr('transform','translate(14,'+(height/2)+') rotate(-90)').attr('text-anchor','middle').attr('fill','#666').attr('font-size',11).text('میانگین سکون (روز) →');
  const g = svg.selectAll('g.node').data(depts).join('g').attr('class','node');
  g.append('circle').attr('cx',d=>x(d.open_pct)).attr('cy',d=>y(d.avg_age_open)).attr('r',d=>r(d.count))
    .attr('fill', d=> (d.open_pct>85 && d.avg_age_open>15) ? ACCENT : d.open_pct>85 ? '#8899aa' : '#c9d3de')
    .attr('opacity',0.85).attr('stroke','#fff').attr('stroke-width',1.5)
    .append('title').text(d=>d.name+'\nباز: '+faNum(d.open_pct)+'% | سکون: '+faNum(d.avg_age_open)+' روز | حجم: '+fa(d.count));
  g.append('text').attr('class','rm-label').attr('x',d=>x(d.open_pct)).attr('y',d=>y(d.avg_age_open)-r(d.count)-6).attr('text-anchor','middle').text(d=>d.name);
}
window.addEventListener('resize', ()=>drawRiskMatrix());

/* ================= initHierarchyViews: بازنشانی و رسم کامل Treemap/درخت‌شاخه‌ای/نقشهٔ ریسک =================
   بعد از هر Fetch فیلتر (DATA/HIER جدید) دوباره صدا زده می‌شود؛ وضعیت Drill-down به سطح اول برمی‌گردد. */
