/* ================= فیلتر: fetch با format=json + جایگزینی درجای بخش‌های داشبورد =================
   دو روش قبلی هر دو شکست خوردند: (۱) fetch + document.write کل صفحه را در همان window/Scope فعلی
   بازنویسی می‌کرد و روی «const DATA» با خطای «already been declared» کل اسکریپت را می‌کشت.
   (۲) یک Shell بیرونی + iframe داخلی، که وقتی از منوی واقعی Teamyar (خودش بات را داخل Iframe/شِل
   خودش می‌گذارد) باز می‌شد اصلاً HTML لود نمی‌شد (به‌احتمال زیاد به‌خاطر Sandbox آن Iframe اصلی).
   این نسخه هیچ Document/Window تازه‌ای نمی‌سازد — همان صفحهٔ در حال اجرا را با fetch به‌روزرسانی
   می‌کند: Query دوباره سمت سرور اجرا می‌شود (format=json)، و فقط innerHTML بخش‌های داشبورد + نمونهٔ
   نمودارها/D3 در جا (بدون Navigate، بدون iframe/document.write) بازسازی می‌شوند. */
var filterFormEl = document.getElementById('filterForm');
var filterRequestInFlight = false; // قفل ساده جلوی Submitهای هم‌پوشان — بدون این، دو fetch موازی هر دو
                                    // initCharts() را صدا می‌زنند و روی هم Canvas را می‌گیرند («Canvas is
                                    // already in use... must be destroyed before...» از Chart.js)
if (filterFormEl) {
  filterFormEl.addEventListener('submit', function (e) {
    e.preventDefault();
    if (filterRequestInFlight) return;
    filterRequestInFlight = true;

    var btn = document.getElementById('filterSubmitBtn');
    var originalText = btn ? btn.textContent : '';
    if (btn) { btn.disabled = true; btn.textContent = 'در حال بارگذاری...'; }

    var formData = new FormData(filterFormEl);
    formData.set('format', 'json');

    fetch(window.location.href, { method: 'POST', body: formData })
      .then(function (res) {
        if (!res.ok) throw new Error('HTTP ' + res.status);
        return res.json();
      })
      .then(function (payload) {
        if (!payload.ok) throw new Error(payload.error || 'خطای ناشناخته سمت سرور');
        applyDashboardUpdate(payload);
      })
      .catch(function (err) {
        alert('خطا در اعمال فیلتر: ' + err.message);
      })
      .finally(function () {
        filterRequestInFlight = false;
        if (btn) { btn.disabled = false; btn.textContent = originalText; }
      });
  });
}

function applyDashboardUpdate(payload){
  DATA = payload.dash_data;
  HIER = payload.hier;

  document.getElementById('headerSubText').innerHTML = payload.header_sub_html;
  document.getElementById('heroPills').innerHTML = payload.hero_pills_html;
  document.getElementById('kpiGrid').innerHTML = payload.kpi_cards_html;
  document.getElementById('insightsContainer').innerHTML = payload.insights_html;
  document.getElementById('bottleneckTbody').innerHTML = payload.bottleneck_rows_html;
  document.getElementById('authorTbody').innerHTML = payload.author_rows_html;
  document.getElementById('authorBusFactor').innerHTML = payload.author_bus_factor_html;
  document.getElementById('responsibleTbody').innerHTML = payload.responsible_rows_html;
  document.getElementById('responsibleBusFactor').innerHTML = payload.responsible_bus_factor_html;
  document.getElementById('departmentTbody').innerHTML = payload.department_rows_html;
  document.getElementById('detailTbody').innerHTML = payload.detail_rows_html;
  document.getElementById('footerText').innerHTML = payload.footer_html;

  initCharts();
  initHierarchyViews();
  window.scrollTo({ top: 0, behavior: 'smooth' });
}

/* ---------------- Toolbar: fullscreen / excel / help ---------------- */
function toggleFullScreen(){
  var root = document.getElementById('reportRoot');
  var isFull = document.fullscreenElement || document.webkitFullscreenElement;
  if(!isFull){ if(root.requestFullscreen) root.requestFullscreen(); else if(root.webkitRequestFullscreen) root.webkitRequestFullscreen(); }
  else { if(document.exitFullscreen) document.exitFullscreen(); else if(document.webkitExitFullscreen) document.webkitExitFullscreen(); }
}
function openHelp(){ document.getElementById('helpModal').classList.add('active'); }
function closeHelp(){ document.getElementById('helpModal').classList.remove('active'); }
window.onclick = function(e){ if(e.target===document.getElementById('helpModal')) closeHelp(); };
document.addEventListener('keydown', function(e){ if(e.key==='Escape') closeHelp(); });

function csvCell(t){ t=(t==null?'':String(t)).replace(/\s+/g,' ').trim(); if(t.indexOf(',')!==-1||t.indexOf('"')!==-1) t='"'+t.replace(/"/g,'""')+'"'; return t; }
function downloadCsv(lines, fileName){
  var blob = new Blob(['﻿'+lines.join('\r\n')], {type:'text/csv;charset=utf-8;'});
  var url = URL.createObjectURL(blob); var link = document.createElement('a');
  link.href=url; link.download=fileName; document.body.appendChild(link); link.click(); document.body.removeChild(link); URL.revokeObjectURL(url);
}
function exportToExcel(){
  var table = document.getElementById('detailTable'); if(!table) return;
  var lines=[]; var heads = table.querySelectorAll('thead th'); var hl=[];
  for(var h=0;h<heads.length;h++) hl.push(csvCell(heads[h].innerText));
  lines.push(hl.join(','));
  var rows = table.querySelectorAll('tbody tr');
  for(var i=0;i<rows.length;i++){ var cells=rows[i].querySelectorAll('td'); var line=[];
    for(var c=0;c<cells.length;c++) line.push(csvCell(cells[c].innerText)); lines.push(line.join(',')); }
  downloadCsv(lines, 'جزئیات-اقدام-ها.csv');
}

/* ---------------- Sortable tables ---------------- */
function getCellSortValue(cell){
  var text = cell? cell.innerText.trim(): '';
  var n = text.replace(/[,%]/g,'').trim();
  if(n!==''&&/^-?\d+(\.\d+)?$/.test(n)) return parseFloat(n);
  return text;
}
function sortTableByColumn(table, colIndex, dir){
  var tbody = table.querySelector('tbody');
  var rows = Array.prototype.slice.call(tbody.querySelectorAll('tr'));
  rows.sort(function(ra,rb){ var a=getCellSortValue(ra.children[colIndex]), b=getCellSortValue(rb.children[colIndex]), cmp;
    if(typeof a==='number'&&typeof b==='number') cmp=a-b; else cmp=String(a).localeCompare(String(b),'fa');
    return dir==='asc'?cmp:-cmp; });
  rows.forEach(function(row){ tbody.appendChild(row); });
}
function initSortableTables(){
  document.querySelectorAll('table.data-table').forEach(function(table){
    var headers = table.querySelectorAll('thead th');
    headers.forEach(function(th, colIndex){
      th.addEventListener('click', function(){
        var dir = th.classList.contains('sort-asc') ? 'desc' : 'asc';
        headers.forEach(function(h){ h.classList.remove('sort-asc','sort-desc'); });
        th.classList.add(dir==='asc'?'sort-asc':'sort-desc');
        sortTableByColumn(table, colIndex, dir);
      });
    });
  });
}
initSortableTables();
</script>
