  <div class="modal-body">
    <p>این داشبورد وضعیت کلی «اقدام‌ها» (todo_task) و مراحل فرآیندی سازمان را بر پایهٔ دادهٔ زندهٔ Teamyar تحلیل می‌کند.</p>
    <h4>مفاهیم کلیدی</h4>
    <ul>
      <li><b>باز/بسته:</b> اقدام «بسته» یعنی فرآیندش به پایان رسیده (T_REAL_END_DATE پر شده)؛ در غیر این صورت «باز» است.</li>
      <li><b>سکون (Age):</b> برای اقدام‌های باز، فاصلهٔ امروز تا تاریخ شروع اقدام.</li>
      <li><b>عمر تا بسته‌شدن (Lifecycle):</b> برای اقدام‌های بسته، فاصلهٔ شروع تا بسته‌شدن.</li>
      <li><b>گلوگاه:</b> مرحله‌ای از گردش‌کار که بیشترین تعداد اقدام معطل (وضعیت پیش‌نویس) را در خود نگه داشته.</li>
      <li><b>Bus Factor:</b> سهم نفرات برتر از کل بار کاری — هرچه بالاتر، ریسک تک‌نقطه‌ای بیشتر است.</li>
    </ul>
    <h4>تعامل‌ها</h4>
    <ul>
      <li>فیلترهای بالای صفحه (تاریخ/واحد/جریان‌کار/مسئول مرحلهٔ جاری/وضعیت) کل داشبورد را بر اساس اقدام‌هایی که <b>در بازه شروع شده‌اند</b> فیلتر می‌کنند. فیلتر «مسئول مرحلهٔ جاری» فقط اقدام‌هایی را نشان می‌دهد که همین الان حداقل یک مرحلهٔ پیش‌نویس/جاری به آن فرد سپرده شده باشد.</li>
      <li>روی نمودار درختی (Treemap) کلیک کنید تا وارد سطح بعد شوید؛ از مسیر نان‌ریزه (Breadcrumb) بالا برگردید.</li>
      <li>روی گره‌های نمودار شاخه‌ای کلیک کنید تا باز/بسته شود.</li>
      <li>روی هدر ستون جدول‌ها کلیک کنید تا صعودی/نزولی مرتب شود.</li>
      <li>روی شناسهٔ اقدام (#) در جدول تفصیلی کلیک کنید تا جزئیات همان اقدام در تب جدید باز شود.</li>
      <li>تمام‌صفحه / خروجی Excel (از جدول تفصیلی) از نوار ابزار بالا در دسترس است.</li>
    </ul>
    <h4>محدودیت شناخته‌شده (v01)</h4>
    <ul><li>بخش «ماژول اجرایی» در این نسخه وجود ندارد — منبع دادهٔ معتبری برای آن در schema فعلی یافت نشد.</li></ul>
  </div>
</div></div>
]])

    table.insert(html, '<script id="dashData" type="application/json">' .. dash_json .. '</script>\n')
    table.insert(html, '<script id="hierData" type="application/json">' .. hier_json .. '</script>\n')
    table.insert(html, REPORT_JS_BODY)
    table.insert(html, '</div>\n</body>\n</html>')

    return table.concat(html)
end

-- توجه: یک نسخهٔ قبلی این‌جا سعی کرد با یک Shell بیرونی + iframe داخلی، Submit فیلتر را به‌جای
-- Navigate کامل صفحه، فقط داخل iframe محدود کند. آن نسخه در تست مستقیم (Navigate خام به URL بات)
-- درست کار می‌کرد، ولی وقتی از منوی واقعی Teamyar (که خودش بات را داخل Iframe/شِل خودش می‌گذارد)
-- باز شد HTML اصلاً لود نشد — به احتمال زیاد چون آن Iframe اصلی Teamyar با Sandbox بدون
-- allow-same-origin اجرا می‌شود، پس Origin که از داخلش دیده می‌شود Opaque است، و iframe تودرتوی
-- من با X-Frame-Options: SAMEORIGIN توسط خود مرورگر رد می‌شد (نه خطای سرور). چون تست مستقیم من
-- این حالت واقعی را شبیه‌سازی نمی‌کرد، این رگرسیون به‌موقع دیده نشد. برگردانده شد به رندر مستقیم
-- (Submit فرم فیلتر = Navigate واقعی صفحه) — کندتر/با فلاش صفحه، ولی همیشه کار می‌کند.

local function render_error_html(message)
    return '<!DOCTYPE html>\n<html dir="rtl" lang="fa">\n<head>\n<meta charset="UTF-8">\n<title>داشبورد اقدام‌ها - خطا</title>\n' ..
        REPORT_CSS ..
        '</head>\n<body>\n<div id="reportRoot" style="max-width:640px;">' ..
        '<div class="card" style="border-color:#e00;text-align:center;margin-top:60px;">' ..
        '<h3 style="color:#c00;">خطا در تولید داشبورد</h3><p>' .. escape_html(message) .. '</p></div>' ..
        '</div>\n</body>\n</html>'
end

-- ============================================================
-- MAIN
-- ============================================================

local function main()
    local input = teamyar.get_input() or {}
    local filters = parse_filters(input)

    local now_raw = fetch_now_raw()
    local where_sql, params, from_raw, to_raw = build_action_where(filters, now_raw)

    local actions = fetch_actions(where_sql, params)
    local step_counts = fetch_step_counts(where_sql, params)
    local pending_steps = fetch_pending_steps(where_sql, params)

    -- فیلتر سن (اختیاری) — فقط روی اقدام‌های باز اعمال می‌شود، بعد از Fetch (حجم دادهٔ بازهٔ پیش‌فرض کوچک است)
    if filters.age_min ~= nil or filters.age_max ~= nil then
        local filtered = {}
        for _, a in ipairs(actions) do
            local keep = true
            if a.status ~= 2 and a.t_start_date > 0 then
                local age = (now_raw - a.t_start_date) / CONFIG.DAY_TICKS
                if filters.age_min and age < filters.age_min then keep = false end
                if filters.age_max and age > filters.age_max then keep = false end
            elseif filters.age_min ~= nil or filters.age_max ~= nil then
                keep = false -- فیلتر سن فقط برای اقدام‌های باز معنی دارد
            end
            if keep then table.insert(filtered, a) end
        end
        actions = filtered

        -- pending_steps/step_counts از همان where_sql (بدون فیلتر سن) آمده‌اند؛ برای هم‌خوانی کامل
        -- گلوگاه/مسئولان با فهرست اقدام‌های فیلترشده، به مجموعهٔ Task ID باقی‌مانده محدودشان می‌کنیم.
        local kept_ids = {}
        for _, a in ipairs(actions) do kept_ids[a.id] = true end
        local filtered_pending = {}
        for _, s in ipairs(pending_steps) do
            if kept_ids[s.task_id] then table.insert(filtered_pending, s) end
        end
        pending_steps = filtered_pending
    end

    local kpi = compute_kpi(actions, step_counts, now_raw)
    local months_order, new_by_month = compute_monthly(actions, now_raw)
    local closed_by_month = compute_closed_monthly(actions)
    local aging = compute_aging(actions, now_raw)
    local departments = compute_departments(actions, now_raw)
    local workflows = compute_workflows(actions, now_raw)
    local bottlenecks = compute_bottlenecks(pending_steps, now_raw)
    local authors, bus_author = compute_authors(actions)
    local responsibles, bus_responsible = compute_responsibles(pending_steps, now_raw)
    local hier = compute_hierarchy(actions)
    local insights = build_insights(kpi, departments, bottlenecks, authors, bus_author, responsibles)
    local detail_rows = build_detail_rows(actions, now_raw)

    local sections, workflow_opts, responsible_opts = fetch_filter_options()

    local dash_data = build_dashboard_json({
        kpi = kpi, months_order = months_order, new_by_month = new_by_month,
        closed_by_month = closed_by_month, aging = aging, departments = departments,
        authors = authors, bus_author = bus_author, responsibles = responsibles,
        bus_responsible = bus_responsible, workflows = workflows, bottlenecks = bottlenecks,
    })

    -- برچسب بازه + مقدار پیش‌فرض Dropdownهای تاریخ شمسی — همه محاسبات تقویم کاملاً سمت Lua
    -- (بدون هیچ Query اضافه)، به دلیل عدم دسترسی به REPORT_FN_JDATE — بالا توضیح داده شد.
    local now_j = filetime_to_jalali(now_raw)
    local from_j = { y = filters.from_jy, m = filters.from_jm, d = filters.from_jd }
    local to_j = { y = filters.to_jy, m = filters.to_jm, d = filters.to_jd }
    if from_j.y == nil then
        local j = filetime_to_jalali(from_raw)
        from_j = j or from_j
    end
    if to_j.y == nil then
        local j = filetime_to_jalali(to_raw)
        to_j = j or to_j
    end
    local range_label = (jalali_date_str(from_raw) or "") .. " تا " .. (jalali_date_str(to_raw) or "")
    local generated_at = jalali_datetime_str(now_raw) or ""

    -- فیلتر بدون Navigate کامل صفحه: JS با fetch همین بات را با format=json صدا می‌زند، Query دوباره
    -- روی سرور اجرا می‌شود (بازه/فیلترهای جدید)، و فقط بخش‌های داشبورد (نه کل بات/صفحه) در جا
    -- به‌روزرسانی می‌شوند. تمام قطعات HTML اینجا از همان توابع render_* استفاده می‌کنند که رندر
    -- اولیهٔ صفحه هم استفاده می‌کند — یک منبع حقیقت، بدون تکرار منطق.
    if input["format"] == "json" then
        teamyar.write_result(json.encode({
            ok = true,
            dash_data = dash_data,
            hier = hier,
            hero_pills_html = render_hero_pills(kpi),
            kpi_cards_html = render_kpi_cards(kpi),
            insights_html = render_insights_html(insights),
            bottleneck_rows_html = render_bottleneck_table(bottlenecks),
            author_rows_html = render_author_table(authors),
            author_bus_factor_html = render_bus_factor_html(bus_author),
            responsible_rows_html = render_responsible_table(responsibles),
            responsible_bus_factor_html = render_bus_factor_html(bus_responsible),
            department_rows_html = render_department_table(departments),
            detail_rows_html = render_detail_table(detail_rows),
            header_sub_html = render_header_sub_html(kpi, range_label),
            footer_html = render_footer_html(generated_at),
        }))
        return
    end

    local filter_bar_html = render_filter_bar(filters,
        { sections = sections, workflows = workflow_opts, responsibles = responsible_opts },
        from_j, to_j, now_j.y)

    local html = render_html({
        kpi = kpi,
        dash_data = dash_data,
        hier = hier,
        range_label = range_label,
        generated_at = generated_at,
        filter_bar_html = filter_bar_html,
        insights_html = render_insights_html(insights),
        bottleneck_rows = render_bottleneck_table(bottlenecks),
        author_rows = render_author_table(authors),
        bus_author = bus_author,
        responsible_rows = render_responsible_table(responsibles),
        bus_responsible = bus_responsible,
        department_rows = render_department_table(departments),
        detail_rows = render_detail_table(detail_rows),
    })

    teamyar.write_result(html)
end

local ok, err = pcall(main)
if not ok then
    teamyar.write_result(render_error_html(tostring(err)))
end
